import bpy, os
from mathutils import Vector
expected=os.path.normcase(os.path.normpath(r'C:\mcp-blender\salvador_lacerda_do_zero.blend'))
if os.path.normcase(os.path.normpath(bpy.data.filepath))!=expected: raise RuntimeError('arquivo errado')
c=bpy.data.collections.get('01 WORLD | ELEVADOR LACERDA | blockout v4')
if not c: raise RuntimeError('v4 ausente')
for key in ('torre','passadico','piso terreo','parede frontal','porta entrada','janela frontal'):
    print('---',key,'---')
    for o in c.objects:
        if key in o.name.lower() and o.type=='MESH':
            pts=[o.matrix_world@Vector(x) for x in o.bound_box]; zs=[p.z for p in pts]
            print(f'{o.name}|Z={min(zs):.2f}..{max(zs):.2f}|locZ={o.location.z:.2f}')
print('VISIBLE TERRAIN:')
for o in bpy.data.objects:
    if o.type=='MESH' and ('terreno' in o.name.lower() or 'terrain' in o.name.lower()):
        if not o.hide_viewport and any(not uc.hide_viewport for uc in o.users_collection): print(o.name)
print('AUDIT_V4_Z_OK')
